import {FileSystem, fsNodeFromDraft, type FileSystemNode} from "@core/core-ui/file-system";
import {Share2} from "lucide-react";

const FILE_TYPES = [
  {id: "pipeline", label: "Pipeline", icon: Share2, app: "Pipelines"},
];

const [nodes, setNodes] = useState<FileSystemNode[]>([
  {id: "root", name: "Acme", kind: "root", parentId: null, updatedAt: "Today", updatedTs: 1},
  {id: "p1", name: "Site A", kind: "project", parentId: "root", updatedAt: "Today", updatedTs: 2},
]);

<FileSystem
  nodes={nodes}
  rootId="root"
  fileTypes={FILE_TYPES}
  openLabel={(node) => (node.ref ? "Open in Pipelines" : undefined)}
  onOpenFile={(node) => router.push(hrefFor(node.ref))}
  onCreate={(draft) => {
    const node = fsNodeFromDraft(draft, crypto.randomUUID());
    setNodes((prev) => [...prev, node]);
    return node;
  }}
/>
